CREATE TEMPORARY VIEW every_scene_data_${grass_region_without_quote} AS
SELECT
     a.is_item_card,
     a.is_ads,
     a.mapping_general,
     c.exp_group_id,
     net_order_cnt,
     nmv,
     a.nmv_local,
     a.local_date
FROM (
    SELECT
          user_id
        , mapping_general
        , if(grouping(cast(is_ads as string)) = 1, '__ALL__', cast(is_ads as string)) as is_ads
        , if(grouping(is_item_card) = 1, '__ALL__', is_item_card) as is_item_card
        , local_date
        , sum(net_order_cnt) AS net_order_cnt
        , sum(nmv) AS nmv
        , sum(nmv_local) AS nmv_local
    FROM srdi_mart.dws_sr_data_warehouse_tc_nmv_basic_aggr_r7d_1d
    WHERE grass_region IN (${grass_region})
      AND local_date BETWEEN date_sub(${local_date}, 7) AND ${local_date}
      AND mapping_general NOT IN ('Video', 'Live Streaming')
    GROUP BY
          is_item_card
        , user_id
        , cast(is_ads as string)
        , mapping_general
        , local_date
    GROUPING SETS (
          (user_id, mapping_general, cast(is_ads as string), is_item_card, local_date)
        , (user_id, mapping_general, is_item_card, local_date)
        , (user_id, mapping_general, cast(is_ads as string), local_date)
        , (user_id, mapping_general, local_date)
    )
) a
JOIN user_exp_${grass_region_without_quote} c
  ON a.user_id = c.user_id
 AND a.local_date = c.local_date

;
--sql_divide_splitter--
CREATE TEMPORARY VIEW scene_aggr_data_${grass_region_without_quote} AS
SELECT
     is_item_card,
     is_ads,
     mapping_general,
     exp_group_id,
     sum(net_order_cnt) AS net_order_cnt,
     sum(nmv) AS nmv,
     sum(nmv_local) AS nmv_local,
     local_date
FROM  every_scene_data_${grass_region_without_quote}
GROUP BY
     exp_group_id,
     is_ads,
     is_item_card,
     mapping_general,
     local_date
;
--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_exp_scene_nmv_aggr_r7d_1d
partition (grass_region = ${grass_region},local_date)
select
     is_ads
    ,is_item_card
    ,a.exp_group_id
    ,b.exp_group_type
    ,null as rule_ids
    ,b.layer_id
    ,mapping_general

    ,net_order_cnt
    ,nmv
    ,nmv_local

    ,local_date
from scene_aggr_data_${grass_region_without_quote} a
left join exp_info_${grass_region_without_quote} b on a.exp_group_id=b.exp_group_id
